sys_script_include.script:
var FleetConfig = Class.create();

FleetConfig.PREFIX = 'x_1850693_enterp_0.';

/**
 * FLEET-27: fallbacks used only when a property is missing or empty.
 * The real values live in the Fleet Management system properties.
 */
FleetConfig.DEFAULTS = {
    'pm.interval_miles': 5000,
    'pm.interval_days': 180,
    'sla.assignment_hours': 2,
    'cancellation.grace_hours': 4,
    'no_show.release_minutes': 60,
    'license.expiry_warning_days': 30,
    'fuel.auto_match_miles_tolerance': 50,
    'max_reservation_days': 30,
    'blackout_check_enabled': true,
    'approval.escalation_hours': 24,
    'violation.escalation_days': 30,
    'violation.block_days': 45,
    'document.expiry_warning_days': 30,
    'maintenance.approval_threshold': 0,
    'maintenance.default_duration_days': 1
};

/**
 * Returns a Fleet property value typed like its default (number / boolean / string).
 * @param {string} name - property name with or without the scope prefix, e.g. 'pm.interval_miles'
 * @param {*} [fallback] - overrides the built-in default
 * @returns {number|boolean|string}
 */
FleetConfig.get = function(name, fallback) {
    var key = name.indexOf(FleetConfig.PREFIX) === 0 ? name.substring(FleetConfig.PREFIX.length) : name;
    var def = (typeof fallback !== 'undefined') ? fallback : FleetConfig.DEFAULTS[key];
    var raw = gs.getProperty(FleetConfig.PREFIX + key);
    if (raw === null || typeof raw === 'undefined' || String(raw).trim() === '') {
        return def;
    }
    raw = String(raw).trim();
    if (typeof def === 'boolean') {
        return raw === 'true';
    }
    if (typeof def === 'number') {
        var n = Number(raw);
        return isNaN(n) ? def : n;
    }
    return raw;
};

FleetConfig.prototype = {
    initialize: function() {},
    type: 'FleetConfig'
};
